<section class="overflow-hidden rounded-lg border border-border bg-surface" x-data="{hazard:'grava', revealed:false, data:{grava:{title:'Grava en la curva',icon:'🪨',clue:'Menos adherencia al girar o frenar.',plan:'Reducí antes, mantené una trayectoria estable y evitá movimientos bruscos.'},lluvia:{title:'Superficie mojada',icon:'🌧️',clue:'Más distancia para detenerse y menor visibilidad.',plan:'Aumentá el margen y frená progresivamente antes de la zona difícil.'},bus:{title:'Punto ciego',icon:'🚌',clue:'El vehículo grande puede ocultarte y girar.',plan:'No permanezcás a su lado; reducí y recuperá una posición visible con distancia.'}}}">
    <header class="border-b border-border px-4 py-3"><p class="text-xs font-bold uppercase tracking-wide text-primary">Radar ciclista</p><h4 class="mt-1 font-heading text-lg font-bold">Detectá antes de entrar al peligro</h4></header>
    <div class="relative grid min-h-56 place-items-center overflow-hidden bg-slate-500 p-5 text-center" role="img" :aria-label="data[hazard].title+'. '+data[hazard].clue"><div class="absolute inset-x-0 bottom-0 h-24 bg-slate-700"><span class="absolute left-1/2 top-2 text-5xl" x-text="data[hazard].icon" aria-hidden="true"></span></div><span class="relative -translate-x-20 text-6xl transition-transform duration-500 motion-reduce:transition-none" :class="revealed?'translate-x-0':'-translate-x-20'" aria-hidden="true">🚲</span><span class="absolute left-3 top-3 rounded-full bg-white/90 px-3 py-2 text-xs font-bold text-slate-900" x-text="data[hazard].title"></span></div>
    <div class="p-4"><p class="text-sm text-text-secondary" x-text="data[hazard].clue"></p><div x-show="revealed" x-cloak class="mt-3 rounded-md bg-success/10 p-3 text-sm leading-6 text-success-text" aria-live="polite"><strong>Plan con margen:</strong> <span x-text="data[hazard].plan"></span></div><button type="button" class="mt-3 min-h-11 w-full rounded-md bg-primary px-4 text-sm font-bold text-white" @click="revealed=!revealed" x-text="revealed?'Ocultar plan':'Mostrar decisión segura'"></button><div class="mt-3 grid grid-cols-3 gap-2"><button type="button" class="min-h-11 rounded-md border text-sm font-bold" :class="hazard==='grava'?'border-primary bg-primary/10':'border-border'" @click="hazard='grava';revealed=false">🪨 Grava</button><button type="button" class="min-h-11 rounded-md border text-sm font-bold" :class="hazard==='lluvia'?'border-primary bg-primary/10':'border-border'" @click="hazard='lluvia';revealed=false">🌧️ Lluvia</button><button type="button" class="min-h-11 rounded-md border text-sm font-bold" :class="hazard==='bus'?'border-primary bg-primary/10':'border-border'" @click="hazard='bus';revealed=false">🚌 Bus</button></div></div>
</section>
